import hashlib, importlib.util, json, os, platform, re
from pathlib import Path

root=Path.cwd()
spec=importlib.util.spec_from_file_location('bench',root/'scripts/benchmark_snapshot_integration.py')
bench=importlib.util.module_from_spec(spec); spec.loader.exec_module(bench)
out=root.parent/'ablation-results'; out.mkdir(exist_ok=False)
fixtures=out/'fixtures'; fixtures.mkdir()
env=dict(os.environ,GOMAXPROCS='2',CGO_ENABLED='0',TMPDIR=str(fixtures))
report={'scope':'Corrected hybrid vs flat, identical watch-cache and reconstruction fixes; native preparation and separate GC diagnostics.', 'platform':platform.platform(),'script':Path(__file__).read_text(),'versions':{},'orders':[], 'filesystem':bench.filesystem(fixtures,env,out,'fixture-filesystem')}
cases={'snapshot':('./internal/snapshot','^BenchmarkWatchPreparation$','5x',6),'memory':('./internal/manifest','^BenchmarkSnapshotRetention$','1x',6)}
for name,source in [('hybrid',root.parent/'hybrid'),('flat',root)]:
 directory=out/name; directory.mkdir()
 bench.run(['go','test','./internal/manifest'],source,env,directory/'tests.txt')
 files=sorted([*source.rglob('*.go'),source/'go.mod',source/'go.sum'])
 digest=hashlib.sha256()
 for p in files: digest.update(str(p.relative_to(source)).encode()+b'\0'+p.read_bytes()+b'\0')
 report['versions'][name]={'source_sha256':digest.hexdigest(),'binaries':{},'samples':[]}
 for key,(package,_,_,_) in cases.items():
  binary=directory/(key+'.test')
  bench.run(['go','test','-c','-o',str(binary),package],source,env,directory/('build-'+key+'.txt'))
  report['versions'][name]['binaries'][key]=hashlib.sha256(binary.read_bytes()).hexdigest()
for number in range(3):
 order=['hybrid','flat'] if number%2==0 else ['flat','hybrid']; report['orders'].append(order)
 for name in order:
  directory=out/name; source=root if name=='flat' else root.parent/'hybrid'
  for key,(_,pattern,duration,count) in cases.items():
   raw=bench.run([str(directory/(key+'.test')),'-test.v','-test.run=^$','-test.bench='+pattern,'-test.benchtime='+duration,'-test.benchmem','-test.timeout=10m'],source,env,directory/(str(number)+'-'+key+'.txt'))
   samples=[]
   for line in raw.splitlines():
    m=re.match(r'^(Benchmark\S+)-\d+\s+(\d+)\s+(.+)$',line)
    if m:
     metrics=m[3].split(); samples.append({'name':m[1],'iterations':int(m[2]),'round':number,'metrics':{metrics[i+1]:float(metrics[i]) for i in range(0,len(metrics),2)}})
   if len(samples)!=count: raise RuntimeError((key,len(samples),count))
   report['versions'][name]['samples']+=samples
  (out/'report.json').write_text(json.dumps(report,indent=2)+'\n')
  print(f'Round {number+1}/3: {name} complete',flush=True)
for name in report['versions']:
 for key in cases: (out/name/(key+'.test')).unlink()

